#### Bond Valuation ####import numpy as np# Generate payment times and undiscounted contractual cash flows for a fixed-coupon bond.def bond_cash_flows(    nominal,    coupon_rate,    maturity,    frequency=1,):    if nominal <= 0:        raise ValueError("nominal must be greater than zero.")    if coupon_rate < 0:        raise ValueError("coupon_rate must be non-negative.")    if maturity <= 0:        raise ValueError("maturity must be greater than zero.")    if not isinstance(frequency, int) or frequency <= 0:        raise ValueError("frequency must be a positive integer.")    n_payments = maturity * frequency    if not float(n_payments).is_integer():        raise ValueError(            "maturity * frequency must result in a whole number of payments."        )    n_payments = int(n_payments)    coupon_payment = nominal * coupon_rate / frequency    times = np.arange(1, n_payments + 1) / frequency    cash_flows = np.full(n_payments, coupon_payment, dtype=float)    cash_flows[-1] += nominal    return times, cash_flows# Calculate the present value of a bond using a risk-free curve and credit spread.def bond_price(    times,    cash_flows,    risk_free_rates,    spread,):    times = np.asarray(times, dtype=float)    cash_flows = np.asarray(cash_flows, dtype=float)    risk_free_rates = np.asarray(risk_free_rates, dtype=float)    if times.ndim != 1 or cash_flows.ndim != 1:        raise ValueError("times and cash_flows must be one-dimensional.")    if risk_free_rates.ndim > 1:        raise ValueError("risk_free_rates must be a scalar or one-dimensional.")    if len(times) != len(cash_flows):        raise ValueError("times and cash_flows must have the same length.")    if risk_free_rates.ndim == 1 and len(risk_free_rates) != len(times):        raise ValueError(            "risk_free_rates must be a scalar or have the same length as times."        )    discount_factors = np.exp(-(risk_free_rates + spread) * times)    return np.sum(cash_flows * discount_factors)# Calculate the implied credit spread using the bisection method.def implied_spread(    market_value,    times,    cash_flows,    risk_free_rates,    lower=-0.10,    upper=1.00,    tol=1e-8,    max_iter=1000,):    if market_value <= 0:        raise ValueError("market_value must be greater than zero.")    if lower >= upper:        raise ValueError("lower must be smaller than upper.")    if tol <= 0:        raise ValueError("tol must be greater than zero.")    if max_iter <= 0:        raise ValueError("max_iter must be greater than zero.")    def objective(spread):        return bond_price(            times=times,            cash_flows=cash_flows,            risk_free_rates=risk_free_rates,            spread=spread,        ) - market_value    f_lower = objective(lower)    f_upper = objective(upper)    if f_lower * f_upper > 0:        raise ValueError(            "Bisection interval does not bracket the implied spread."        )    for _ in range(max_iter):        midpoint = (lower + upper) / 2        f_midpoint = objective(midpoint)        if abs(f_midpoint) < tol:            return midpoint        if f_lower * f_midpoint <= 0:            upper = midpoint        else:            lower = midpoint            f_lower = f_midpoint    raise RuntimeError("Implied spread did not converge.")